export function identifyMarginfiAccount(
  account: { data: ReadonlyUint8Array } | ReadonlyUint8Array
): MarginfiAccountType {
  const data = "data" in account ? account.data : account;
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([142, 49, 166, 242, 50, 66, 97, 188])
      ),
      0
    )
  ) {
    return MarginfiAccountType.Bank;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([49, 207, 31, 34, 67, 225, 169, 186])
      ),
      0
    )
  ) {
    return MarginfiAccountType.BankMetadata;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([6, 100, 107, 60, 164, 226, 56, 97])
      ),
      0
    )
  ) {
    return MarginfiAccountType.ExecuteOrderRecord;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([63, 224, 16, 85, 193, 36, 235, 220])
      ),
      0
    )
  ) {
    return MarginfiAccountType.FeeState;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([95, 116, 23, 132, 89, 210, 245, 162])
      ),
      0
    )
  ) {
    return MarginfiAccountType.LiquidationRecord;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([67, 178, 130, 109, 126, 114, 28, 42])
      ),
      0
    )
  ) {
    return MarginfiAccountType.MarginfiAccount;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([182, 23, 173, 240, 151, 206, 182, 67])
      ),
      0
    )
  ) {
    return MarginfiAccountType.MarginfiGroup;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([134, 173, 223, 185, 77, 86, 28, 51])
      ),
      0
    )
  ) {
    return MarginfiAccountType.Order;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([222, 21, 195, 149, 193, 72, 219, 31])
      ),
      0
    )
  ) {
    return MarginfiAccountType.SameAssetEmodeRegistry;
  }
  if (
    containsBytes(
      data,
      fixEncoderSize(getBytesEncoder(), 8).encode(
        new Uint8Array([157, 140, 6, 77, 89, 173, 173, 125])
      ),
      0
    )
  ) {
    return MarginfiAccountType.StakedSettings;
  }
  throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__FAILED_TO_IDENTIFY_ACCOUNT, {
    accountData: data,
    programName: "marginfi",
  });
}

